SELECT status, CASE WHEN cost >= 96 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, AVG(cost) FILTER (WHERE status = 'DELIVERED') AS delivered_avg_cost, COUNT_IF(status = 'RETURNED') AS returned_events, COUNT(DISTINCT id) AS distinct_ids, GROUPING_ID() AS grouping_id FROM shipments GROUP BY CUBE (status, CASE WHEN cost >= 96 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING AVG(cost) FILTER (WHERE status = 'DELIVERED') >= 0 ORDER BY returned_events DESC;
